signal hu1,hu2,hu3,hu4,hu5,hu6,hu7,hu8,hu9 : integer range 0 to 15;
signal sig_low,sig_high,sig_hh : std_logic;
signal c1: integer range 0 to 1000000;
signal c2: integer range 0 to 1000000;

begin
   flag_out <= flag;
	
	with flag select
	 out1 <= ll1 when "01",
	       hh1 when "10",
			 hhu4 when "11",
			 0 when others;
	with flag select
	 out2 <= ll2 when "01",
	       hh2 when "10",
			 hhu5 when "11",
			 0 when others;
	with flag select
	 out3 <= ll3 when "01",
	       hh3 when "10",
		    hhu6 when "11",
			 0 when others;
	with flag select
	 out4 <= ll4 when "01",
	       hh4 when "10",
			 hhu7 when "11",
			 0 when others;
	with flag select
	 out5 <= ll5 when "01",
	       hh5 when "10",
			 hhu8 when "11",
			 0 when others;
	with flag select
	 out6 <= ll6 when "01",
	       hh6 when "10",
			 hhu9 when "11",
			 0 when others;
	 
	with flag select
	 sig_low <= sig when "01",
			 '0' when others;
	with flag select
	 sig_high <= sig when "10",
			 '0' when others;	
	with flag select
	 sig_hh <= sig when "11",
			 '0' when others; 
		
	process(clk_h,sig_low,flag)
    begin
	 if(flag="01") then
	  if(clk_h'event and clk_h = '1') then 
     if(sig_low<='0') then
		c2<=c2+1;
     else
      c2<=0;
     end if;
	 end if;
	 end if;
	end process;
	
	process(sig_low,flag)
    begin
	 if(flag="01") then
	  if(sig_low'event and sig_low = '1') then 
      c1<=c2;
	  end if;
	 end if;
	end process;

	process(clk_l,flag)
    begin
	 if(flag="01") then
	  if(clk_l'event and clk_l = '1') then 
		  ll1<=0;
	     ll2<=l1(c1);
	     ll3<=l2(c1);
	     ll4<=l3(c1);
	     ll5<=l4(c1);
	     ll6<=l5(c1);
	    end if;
	 end if;
	end process;
	
	process(sig_high,clk_l,flag)
	 begin
	 if(flag="10") then
	 if(sig_high'event and sig_high='1')then
	  if(clk_l='1') then
	   h1<=0;h2<=0;h3<=0;h4<=0;h5<=0;h6<=0;
     else
      if h1=9 then h1<=0; 
       if h2=9 then h2<=0; 
        if h3=9 then h3<=0; 
         if h4=9 then h4<=0; 
          if h5=9 then h5<=0; 
           if h6=9 then h6<=0;
           else h6<=h6+1;
           end if;
          else h5<=h5+1;
          end if;
         else h4<=h4+1;
         end if;
        else h3<=h3+1;
        end if;
       else h2<=h2+1;
       end if;
      else h1<=h1+1;
      end if;
     end if;
	 end if;
	 end if;
	end process;
	
	process(clk_l,flag)
    begin
	 if(flag="10") then
	  if(clk_l'event and clk_l = '1') then
        hh1<=h1;hh2<=h2;hh3<=h3;hh4<=h4;hh5<=h5;hh6<=h6;
	    end if;
	 end if;
	end process;
	
	process(sig_hh,clk_l,flag)
	 begin
	 if(flag="11") then
	 if(sig_hh'event and sig_hh='1')then
	  if(clk_l='1') then
	   hu1<=0;hu2<=0;hu3<=0;hu4<=0;hu5<=0;hu6<=0;hu7<=0;hu8<=0;hu9<=0;
     else
      if hu1=9 then hu1<=0; 
       if hu2=9 then hu2<=0; 
        if hu3=9 then hu3<=0; 
         if hu4=9 then hu4<=0; 
          if hu5=9 then hu5<=0; 
           if hu6=9 then hu6<=0;
			  if hu7=9 then hu7<=0;
				 if hu8=9 then hu8<=0;
				  if hu9=9 then hu9<=0;
				  else hu9<=hu9+1;
              end if;
				 else hu8<=hu8+1;
             end if;
				else hu7<=hu7+1;
            end if;
           else hu6<=hu6+1;
           end if;
          else hu5<=hu5+1;
          end if;
         else hu4<=hu4+1;
         end if;
        else hu3<=hu3+1;
        end if;
       else hu2<=hu2+1;
       end if;
      else hu1<=hu1+1;
      end if;
     end if;
	 end if;
	 end if;
	end process;
	
	process(clk_l,flag)
    begin
	 if(flag="11") then
	  if(clk_l'event and clk_l = '1') then 
		  hhu1<=hu1;hhu2<=hu2;hhu3<=hu3;hhu4<=hu4;hhu5<=hu5;hhu6<=hu6;hhu7<=hu7;hhu8<=hu8;hhu9<=hu9;
	    end if;
	 end if;
	end process;
end tt;